const n1 = node({type: "n8n-nodes-base.set", version: 3.4, config: {name: "Config", position: [224, 336], parameters: {"mode": "manual", "includeOtherFields": false, "assignments": {"assignments": [{"id": "cfg-run_id", "name": "run_id", "value": expr("{{ \"RUN-\" + $now.setZone(\"Asia/Tokyo\").toFormat(\"yyyyLLdd-HHmm\") }}"), "type": "string"}, {"id": "cfg-run_date", "name": "run_date", "value": expr("{{ $now.setZone(\"Asia/Tokyo\").toFormat(\"yyyy-MM-dd\") }}"), "type": "string"}, {"id": "cfg-run_time", "name": "run_time", "value": expr("{{ $now.setZone(\"Asia/Tokyo\").toFormat(\"HH:mm\") }}"), "type": "string"}, {"id": "cfg-run_started", "name": "run_started", "value": expr("{{ $now.toISO() }}"), "type": "string"}, {"id": "cfg-workflow_name", "name": "workflow_name", "value": "Daily Job Scout V1.0", "type": "string"}, {"id": "cfg-job_threshold", "name": "job_threshold", "value": 80, "type": "number"}, {"id": "cfg-company_threshold", "name": "company_threshold", "value": 90, "type": "number"}, {"id": "cfg-pages_per_query", "name": "pages_per_query", "value": 2, "type": "number"}, {"id": "cfg-max_ai_jobs", "name": "max_ai_jobs", "value": 40, "type": "number"}, {"id": "cfg-staleness_days", "name": "staleness_days", "value": 180, "type": "number"}, {"id": "cfg-allow_hourly_sectors", "name": "allow_hourly_sectors", "value": "農業,漁業", "type": "string"}, {"id": "cfg-ai_model_extract", "name": "ai_model_extract", "value": "claude-haiku-4-5-20251001", "type": "string"}, {"id": "cfg-ai_model_score", "name": "ai_model_score", "value": "claude-sonnet-5-5", "type": "string"}, {"id": "cfg-notion_job_ds_id", "name": "notion_job_ds_id", "value": "a5cfe2a2-de3f-426c-8449-77f0de1c24c9", "type": "string"}, {"id": "cfg-notion_company_ds_id", "name": "notion_company_ds_id", "value": "a72e12ca-f829-407f-945e-4b87e9195cd2", "type": "string"}]}}, notes: "All tunables live here: thresholds, AI models, caps, Notion data source ids."}, output: [{}]});
const n2 = node({type: "n8n-nodes-base.code", version: 2, config: {name: "Build Search Tasks", position: [448, 336], parameters: {"mode": "runOnceForAllItems", "language": "javaScript", "jsCode": "// Build Search Tasks: one item per (source x sector x page). Disabled sources are skipped (listed in Run Log).\nconst cfg = $('Config').first().json;\nconst pages = Number(cfg.pages_per_query) || 1;\nconst registry = [\n  { source: 'hellowork', enabled: true, sectors: ['介護', '外食', '食品製造', '建設', '農業', '宿泊', 'ビルクリーニング', '製造', '自動車整備', '漁業'] },\n  { source: 'engage', enabled: false, note: 'adapter not built - QC pending' },\n  { source: 'jobmedley', enabled: false, note: 'adapter not built - WAF 403 risk' },\n  { source: 'indeed', enabled: false, note: 'legal/access/rendering QC pending (locked decision)' },\n  { source: 'mintoku', enabled: false, note: 'legal/access/rendering QC pending (locked decision)' }\n];\nconst out = [];\nconst disabled = [];\nfor (const s of registry) {\n  if (!s.enabled) { disabled.push(s.source); continue; }\n  for (const sector of s.sectors) {\n    for (let p = 1; p <= pages; p++) {\n      const url = 'https://hellowork.careers/' + encodeURIComponent('求人') + '?q=' + encodeURIComponent('特定技能 ' + sector) + '&l=&only_hellowork=c&pg=' + p;\n      out.push({ json: { _kind: 'task', source: s.source, sector, page: p, url, run_id: cfg.run_id, sources_disabled: disabled.join(',') } });\n    }\n  }\n}\nreturn out;\n"}, notes: "Source registry. Only hellowork is enabled; engage/jobmedley/indeed/mintoku are disabled placeholders."}, output: [{}]});
const n3 = node({type: "n8n-nodes-base.httpRequest", version: 4.3, config: {name: "Fetch Listing", position: [672, 336], parameters: {"method": "GET", "url": expr("{{ $json.url }}"), "sendHeaders": true, "headerParameters": {"parameters": [{"name": "User-Agent", "value": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"}, {"name": "Accept-Language", "value": "ja,en;q=0.8"}]}, "options": {"timeout": 30000, "response": {"response": {"responseFormat": "text"}}, "batching": {"batch": {"batchSize": 1, "batchInterval": 2500}}}}, retryOnFail: true, maxTries: 3, waitBetweenTries: 4000, onError: "continueRegularOutput", notes: "Per-item errors continue (onError=continueRegularOutput) -> logged by Parse Listing -> Error Log."}, output: [{}]});
const n4 = node({type: "n8n-nodes-base.code", version: 2, config: {name: "Parse Listing", position: [896, 336], parameters: {"mode": "runOnceForAllItems", "language": "javaScript", "jsCode": "// Parse Listing: turns each fetch response into job items + one meta item (or an error item). Pairs back to task via pairedItem.\nconst tasks = $('Build Search Tasks').all();\nconst cfg = $('Config').first().json;\nconst strip = (s) => (s || '').replace(/<br\\s*\\/?>/gi, ' ').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\\s+/g, ' ').trim();\nconst out = [];\nconst inputs = $input.all();\nfor (let k = 0; k < inputs.length; k++) {\n  const it = inputs[k];\n  let task = {};\n  try { task = $('Build Search Tasks').itemMatching(k).json; } catch (e) { task = (tasks[k] || tasks[0] || { json: {} }).json; }\n  const base = { run_id: cfg.run_id, source: task.source, sector: task.sector, page: task.page, task_url: task.url };\n  const html = (it.json && (it.json.data || it.json.body)) || '';\n  if (it.json && it.json.error) {\n    const e = it.json.error;\n    out.push({ json: Object.assign({ _kind: 'error', stage: 'fetch_listing', error_type: (e.code || e.name || 'FETCH_ERROR'), error_message: String(e.message || e).slice(0, 300), retry_status: 'retries_exhausted' }, base) });\n    continue;\n  }\n  if (typeof html !== 'string' || html.length < 2000) {\n    out.push({ json: Object.assign({ _kind: 'error', stage: 'fetch_listing', error_type: 'EMPTY_RESPONSE', error_message: 'response too short (' + (html || '').length + ')', retry_status: 'none' }, base) });\n    continue;\n  }\n  const parts = html.split('<div class=\"row\" id=\"');\n  let n = 0;\n  for (let i = 1; i < parts.length; i++) {\n    const blk = parts[i].slice(0, 6000);\n    const idm = blk.match(/^(\\d{5}-\\d{8})\"/);\n    if (!idm) continue;\n    const job_number = idm[1];\n    const link = (blk.match(/class=jobtitle><a href=\"([^\"]+)\"/) || [])[1] || '';\n    const title = strip((blk.match(/class=jobtitle><a href=\"[^\"]+\">([\\s\\S]*?)<\\/a>/) || [])[1]);\n    const company = strip((blk.match(/<span class=company>([\\s\\S]*?)<\\/span>/) || [])[1]);\n    const location = strip((blk.match(/<span class=\"location\">([\\s\\S]*?)<\\/span>/) || [])[1]);\n    const sm = blk.match(/<td class=snip>\\s*<nobr>([\\s\\S]*?)<\\/nobr>\\s*-\\s*([^<\\n]+)/);\n    const snip = sm ? strip(sm[1] + ' - ' + sm[2]) : '';\n    const office = strip((blk.match(/<span class=sdn>([\\s\\S]*?)<\\/span>/) || [])[1]);\n    const dates = strip((blk.match(/<span class=date>([\\s\\S]*?)<\\/span>/) || [])[1]);\n    const summary = strip((blk.match(/<span class=summary>([\\s\\S]*?)<\\/span>\\s*<\\/div>/) || [])[1]).slice(0, 400);\n    const kft = /<span class=\"kft\">特定技能<\\/span>/.test(blk);\n    out.push({ json: Object.assign({ _kind: 'job', job_key: 'HW-' + job_number, job_number, title, company, location, listing_salary: snip, office, dates_text: dates, summary, kft_in_summary: kft, detail_url: link }, base) });\n    n++;\n  }\n  out.push({ json: Object.assign({ _kind: 'meta', rows_found: n, error_type: '', stage: 'parse_listing' }, base) });\n}\nreturn out;\n"}}, output: [{}]});
