const n7 = node({type: "n8n-nodes-base.code", version: 2, config: {name: "Pre-Filter", position: [1568, 272], parameters: {"mode": "runOnceForAllItems", "language": "javaScript", "jsCode": "// Pre-Filter (deterministic, zero AI cost). Rejects obvious traps; caps AI workload per run.\nconst cfg = $('Config').first().json;\nconst maxAi = Number(cfg.max_ai_jobs) || 40;\nconst AGENCY = /協同組合|事業協同|登録支援機関|登録支援|人材派遣|人材紹介|職業紹介|人材センター|人材サービス|スタッフィング|スタッフサービス|派遣/;\nconst PLATFORM = /デルタマーケティング|京進|グローバル・ビジネス・ネットワーク|ヒノデ|日の出|求人ボックス/;\nconst out = [];\nconst seen = {};\nlet accepted = 0;\nfor (const it of $input.all()) {\n  const j = it.json;\n  if (seen[j.job_key]) continue; // same job found by several sector queries in this run\n  seen[j.job_key] = true;\n  let status = 'candidate';\n  let reason = '';\n  const nameBlob = (j.company || '');\n  if (AGENCY.test(nameBlob)) { status = 'REJECT_PREFILTER'; reason = 'PF1 agency/co-op/dispatch company name'; }\n  else if (PLATFORM.test(nameBlob)) { status = 'REJECT_PREFILTER'; reason = 'PF1 platform operator name'; }\n  else if (!j.job_number || !j.detail_url) { status = 'REJECT_PREFILTER'; reason = 'PF2 missing job number or detail url'; }\n  else if (/^HW-/.test(j.job_key) && !/^\\d{5}-\\d{8}$/.test(j.job_number)) { status = 'REJECT_PREFILTER'; reason = 'PF2 malformed job number'; }\n  else if (accepted >= maxAi) { status = 'DEFERRED'; reason = 'PF9 per-run AI cap reached (' + maxAi + '); retried next run'; }\n  if (status === 'candidate') accepted++;\n  const cand = status === 'candidate';\n  out.push({ json: Object.assign({}, j, { is_candidate: cand, _kind: cand ? 'job' : 'outcome', status: cand ? 'CANDIDATE' : status, reason: reason }) });\n}\nreturn out;\n"}, notes: "Deterministic trap filter + in-run dedup + per-run AI cap. No AI."}, output: [{}]});
const n8 = ifElse({version: 2.2, config: {name: "Is Candidate?", position: [1792, 272], parameters: {"conditions": {"options": {"caseSensitive": true, "leftValue": "", "typeValidation": "strict", "version": 2}, "conditions": [{"id": "2ac79c1e-eed2-1cea-38b6-aaaacda29872", "leftValue": expr("{{ String($json.is_candidate) }}"), "operator": {"type": "string", "operation": "equals"}, "rightValue": "true"}], "combinator": "and"}}}, output: [{}]});
const n9 = node({type: "n8n-nodes-base.httpRequest", version: 4.3, config: {name: "Fetch Detail", position: [2016, 192], parameters: {"method": "GET", "url": expr("{{ $json.detail_url }}"), "sendHeaders": true, "headerParameters": {"parameters": [{"name": "User-Agent", "value": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"}, {"name": "Accept-Language", "value": "ja,en;q=0.8"}]}, "options": {"timeout": 30000, "response": {"response": {"responseFormat": "text"}}, "batching": {"batch": {"batchSize": 1, "batchInterval": 2000}}}}, retryOnFail: true, maxTries: 3, waitBetweenTries: 4000, onError: "continueRegularOutput"}, output: [{}]});
const n10 = node({type: "n8n-nodes-base.code", version: 2, config: {name: "Prepare Extract", position: [2240, 192], parameters: {"mode": "runOnceForAllItems", "language": "javaScript", "jsCode": "// Prepare Extract: HTML -> plain text, deterministic hard facts, Anthropic request body.\nconst cfg = $('Config').first().json;\nconst SYSTEM = `あなたは求人票の「事実抽出」専用エンジンです。入力された求人票テキストに書かれている内容だけをJSONに転記します。推測・補完・一般知識による穴埋めは禁止です。\nルール:\n1. 求人票に明記されていない項目は文字列 \"UNKNOWN\"（数値項目は null）にする。\n2. 数値は求人票の記載をそのまま使う。年収→月収の換算、残業込みの総額計算は禁止。固定残業代は別項目に分ける。\n3. ssw_mention の分類（厳守）:\n   - EXPLICIT_RECRUIT: この求人自体が特定技能外国人を採用対象としていると明記（例: 特定技能の方歓迎/募集/受入可/特定技能1号可）\n   - MANAGEMENT_ROLE: 特定技能外国人を管理・教育・支援する側の仕事（例: 外国人スタッフの管理、登録支援、海外人材対策課）\n   - HR_LABEL: 社員区分や会社紹介の中での単なる言及（例: 特定技能社員、特定技能外国人が在籍中/活躍中）\n   - MENTION_ONLY: 特定技能の語はあるが採用対象かどうか不明\n   - NONE: 言及なし\n4. ssw_evidence_quote は求人票テキストからの一字一句そのままの引用（60字以内）。見つからなければ \"UNKNOWN\"。要約や言い換えは禁止。\n5. company_type: DIRECT_EMPLOYER / STAFFING_AGENCY（派遣・紹介・請負が主業）/ COOPERATIVE（協同組合・監理団体）/ REGISTERED_SUPPORT_ORG / PLATFORM / UNKNOWN。「派遣・請負等」欄が派遣なら STAFFING_AGENCY。\n6. overseas_applicant: 国内在住者のみ・在留カード所持必須・海外在住不可と明記なら DOMESTIC_ONLY、海外からの応募可と明記なら OK、記載なしは UNKNOWN。domestic_evidence_quote に原文引用。（ハローワーク紹介状の記載だけでは DOMESTIC_ONLY にしない）\n7. sector_jp は次のいずれか1つ: 介護 / 外食 / 食品製造 / 製造 / 建設 / 農業 / 宿泊 / ビルクリーニング / 造船・舶用工業 / 自動車整備 / 航空 / その他。\n8. corporate_number は13桁の数字が求人票に明記されている場合のみ。なければ \"UNKNOWN\"。\n9. 出力はJSONオブジェクトのみ。前後の説明文・コードフェンス禁止。\nスキーマ:\n{\"job_title_jp\":\"\",\"company_name_jp\":\"\",\"company_type\":\"\",\"is_dispatch\":\"true|false|UNKNOWN\",\"ssw_mention\":\"\",\"ssw_evidence_quote\":\"\",\"sector_jp\":\"\",\"role_summary_jp\":\"\",\"salary\":{\"type\":\"MONTHLY|HOURLY|DAILY|ANNUAL|UNKNOWN\",\"min\":null,\"max\":null,\"fixed_overtime_amount\":null,\"allowances_text\":\"\",\"calc_note\":\"\"},\"bonus\":\"\",\"salary_increase\":\"\",\"overtime_hours_per_month\":\"\",\"working_hours\":\"\",\"work_days_per_month\":\"\",\"holiday_text\":\"\",\"annual_holidays\":null,\"break_minutes\":\"\",\"housing_text\":\"\",\"japanese_level\":\"\",\"experience\":\"\",\"certificates\":\"\",\"age_limit_text\":\"\",\"nationality_text\":\"\",\"visa_text\":\"\",\"overseas_applicant\":\"\",\"domestic_evidence_quote\":\"\",\"prefecture\":\"\",\"city\":\"\",\"address\":\"\",\"benefits_text\":\"\",\"insurance_text\":\"\",\"selection_text\":\"\",\"quota\":null,\"posted_date_text\":\"\",\"expiry_date_text\":\"\",\"corporate_number\":\"\"}`;\nconst toText = (h) => String(h || '').replace(/<script[\\s\\S]*?<\\/script>/gi, '').replace(/<style[\\s\\S]*?<\\/style>/gi, '').replace(/<br\\s*\\/?>/gi, '\\n').replace(/<\\/(p|div|tr|li|h\\d|table|dt|dd)>/gi, '\\n').replace(/<[^>]+>/g, '\\n').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/\\n[ \\t　]*(?=\\n)/g, '').replace(/\\n{2,}/g, '\\n').trim();\nconst out = [];\nconst inputs = $input.all();\nfor (let k = 0; k < inputs.length; k++) {\n  const it = inputs[k];\n  let job = {};\n  try { job = $('Pre-Filter').itemMatching(k).json; } catch (e) { job = {}; }\n  const err = it.json && it.json.error;\n  const html = (it.json && it.json.data) || '';\n  if (err || typeof html !== 'string' || html.length < 3000) {\n    out.push({ json: Object.assign({}, job, { detail_ok: false, detail_error: err ? String(err.message || err).slice(0, 250) : 'detail response too short (' + (html || '').length + ')' }) });\n    continue;\n  }\n  const full = toText(html);\n  const start = full.indexOf('の募集内容、仕事概要');\n  const body = (start >= 0 ? full.slice(start) : full).slice(0, 9000);\n  const lines = body.split('\\n').map((s) => s.trim()).filter((s) => s.length);\n  const after = (label) => { const i = lines.indexOf(label); return i >= 0 && i + 1 < lines.length ? lines[i + 1] : ''; };\n  const hard = {\n    haken_field: after('派遣・請負等'),\n    employment: after('雇用形態'),\n    wage_monthly_text: after('賃金'),\n    wage_form: after('賃金形態'),\n    annual_holidays_text: after('年間休日'),\n    workhours1: after('就業時間１') || after('就業時間'),\n    posted: (full.match(/受理日：([0-9]{1,2})月([0-9]{1,2})日/) || []).slice(1, 3),\n    expiry: (full.match(/有効期限：([0-9]{1,2})月([0-9]{1,2})日/) || []).slice(1, 3),\n    corporate_number: (body.match(/法人番号[^0-9]{0,6}([0-9]{13})/) || [])[1] || ''\n  };\n  const jobText = body;\n  const userMsg = '求人番号: ' + job.job_number + '\\n掲載サイト一覧の会社名: ' + job.company + '\\n一覧の見出し: ' + job.title + '\\n---求人票本文---\\n' + jobText.slice(0, 7500);\n  out.push({ json: Object.assign({}, job, { detail_ok: true, detail_text: jobText, hard, ai_extract_req: { model: cfg.ai_model_extract, max_tokens: 2000, temperature: 0, system: SYSTEM, messages: [{ role: 'user', content: userMsg }] } }) });\n}\nreturn out;\n"}, notes: "HTML->text, hard facts (dispatch field, wage form, dates, 法人番号), extract prompt."}, output: [{}]});
const n11 = node({type: "n8n-nodes-base.httpRequest", version: 4.3, config: {name: "AI Extract", position: [2464, 192], parameters: {"method": "POST", "url": "https://api.anthropic.com/v1/messages", "authentication": "genericCredentialType", "genericAuthType": "httpTemplatedCustomAuth", "sendHeaders": true, "headerParameters": {"parameters": [{"name": "anthropic-version", "value": "2023-06-01"}, {"name": "content-type", "value": "application/json"}]}, "sendBody": true, "contentType": "json", "specifyBody": "json", "jsonBody": expr("{{ JSON.stringify($json.ai_extract_req) }}"), "options": {"timeout": 90000, "batching": {"batch": {"batchSize": 3, "batchInterval": 1500}}}}, retryOnFail: true, maxTries: 3, waitBetweenTries: 5000, onError: "continueRegularOutput", credentials: {httpTemplatedCustomAuth: newCredential("Anthropic API Key (x-api-key)")}}, output: [{}]});
const n12 = node({type: "n8n-nodes-base.code", version: 2, config: {name: "Gates M1-M8", position: [2688, 192], parameters: {"mode": "runOnceForAllItems", "language": "javaScript", "jsCode": "// Parse Extract + Hard Gates M1-M8 (deterministic). AI output is only DATA here; gates decide.\nconst cfg = $('Config').first().json;\nconst parseJson = (t) => { let s = String(t || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim(); const a = s.indexOf('{'); const b = s.lastIndexOf('}'); if (a < 0 || b < a) return null; try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; } };\nconst norm = (s) => String(s || '').replace(/[\\s　]+/g, '');\nconst nowJ = new Date(Date.now() + 9 * 3600 * 1000);\nconst todayUTC = Date.UTC(nowJ.getUTCFullYear(), nowJ.getUTCMonth(), nowJ.getUTCDate());\nconst md2date = (arr, mode) => { // month/day only -> nearest plausible year\n  if (!arr || arr.length < 2) return null; const m = Number(arr[0]); const d = Number(arr[1]); if (!m || !d) return null;\n  const y = nowJ.getUTCFullYear(); let t = Date.UTC(y, m - 1, d);\n  if (mode === 'posted' && t > todayUTC + 2 * 86400000) t = Date.UTC(y - 1, m - 1, d);\n  if (mode === 'expiry' && t < todayUTC - 200 * 86400000) t = Date.UTC(y + 1, m - 1, d);\n  return t;\n};\nconst wageNum = (s) => { const m = String(s || '').replace(/,/g, '').match(/([0-9]{4,7})/); return m ? Number(m[1]) : null; };\nconst SECTORS = ['介護', '外食', '食品製造', '製造', '建設', '農業', '宿泊', 'ビルクリーニング', '造船・舶用工業', '自動車整備', '航空', 'その他'];\nconst SMAP = { '飲食料品製造業': '食品製造', '工業製品製造業': '製造', '漁業': '農業', '自動車運送業': 'その他', '鉄道': 'その他', '林業': 'その他', '木材産業': 'その他' };\nconst allowHourly = String(cfg.allow_hourly_sectors || '').split(',');\nconst out = [];\nconst inputs = $input.all();\nfor (let k = 0; k < inputs.length; k++) {\n  const it = inputs[k];\n  let job = {};\n  try { job = $('Prepare Extract').itemMatching(k).json; } catch (e) { job = {}; }\n  const base = Object.assign({}, job);\n  delete base.ai_extract_req;\n  const gates = {}; const fails = []; const flags = [];\n  const G = (id, ok, why) => { gates[id] = ok ? 'PASS' : 'FAIL: ' + why; if (!ok) fails.push(id + ' ' + why); };\n  if (job.detail_ok === false) { out.push({ json: Object.assign(base, { _kind: 'outcome', status: 'FETCH_DETAIL_ERROR', reason: job.detail_error, gate_pass: false, gates }) }); continue; }\n  const e = parseJson(it.json && it.json.content && it.json.content[0] && it.json.content[0].text);\n  if (it.json && it.json.error || !e) { out.push({ json: Object.assign(base, { _kind: 'outcome', status: 'AI_ERROR', reason: 'extract failed: ' + (it.json && it.json.error ? String(it.json.error.message || it.json.error).slice(0, 200) : 'unparseable JSON'), gate_pass: false, gates, detail_text: undefined }) }); continue; }\n  const h = job.hard || {}; const text = norm(job.detail_text);\n  const sal = e.salary || {};\n  // ---- M1 real direct employer\n  const agencyRx = /協同組合|事業協同|登録支援機関|人材派遣|人材紹介|職業紹介|派遣/;\n  const haken = /派遣|請負/.test(h.haken_field || '') && !/(ではない|でない|ではありません|なし)/.test(h.haken_field || '') && !/^(-|ー|なし|該当なし)?$/.test((h.haken_field || '').trim());\n  const badType = ['STAFFING_AGENCY', 'COOPERATIVE', 'REGISTERED_SUPPORT_ORG', 'PLATFORM'].indexOf(e.company_type) >= 0;\n  const cname = e.company_name_jp && e.company_name_jp !== 'UNKNOWN' ? e.company_name_jp : job.company;\n  G('M1', !badType && !haken && !agencyRx.test(cname || '') && !!cname, badType ? 'company_type=' + e.company_type : haken ? 'dispatch/contract field: ' + h.haken_field : 'agency-like or missing company name');\n  if (e.company_type === 'UNKNOWN') flags.push('employer_type_unverified');\n  // ---- M2 job IS an SSW job (evidence quote must exist verbatim in the source text)\n  const q = String(e.ssw_evidence_quote || '');\n  const quoteInText = q.length >= 4 && q !== 'UNKNOWN' && text.indexOf(norm(q)) >= 0;\n  const posRx = /募集|歓迎|可能|可$|可。|可）|対象|受入|受け入れ|採用|応募|在留資格|取得|優遇|ＯＫ|OK/;\n  const stateOnly = /在籍|活躍|社員/.test(q) && !posRx.test(q);\n  const mgmtRx = /(外国人|海外人材|技能実習|特定技能).{0,12}(管理|教育|支援|対策|サポート|通訳|担当)/.test((e.job_title_jp || '') + (e.role_summary_jp || ''));\n  let m2 = e.ssw_mention === 'EXPLICIT_RECRUIT' && quoteInText && q.indexOf('特定技能') >= 0 && posRx.test(q) && !stateOnly;\n  let m2why = e.ssw_mention !== 'EXPLICIT_RECRUIT' ? 'ssw_mention=' + e.ssw_mention : !quoteInText ? 'evidence quote not found verbatim in source' : stateOnly ? 'state-only label (在籍/活躍/社員)' : 'quote lacks recruit wording';\n  if (m2 && mgmtRx) { m2 = false; m2why = 'SSW management role (hard reject)'; }\n  G('M2', m2, m2why);\n  // ---- M3 active + dated\n  const expiry = md2date(h.expiry, 'expiry'); const posted = md2date(h.posted, 'posted');\n  const ageDays = posted ? Math.round((todayUTC - posted) / 86400000) : null;\n  G('M3', !!expiry && expiry >= todayUTC, !expiry ? 'no expiry date evidence' : 'posting expired');\n  if (ageDays !== null && ageDays > (Number(cfg.staleness_days) || 180)) flags.push('stale_over_' + (Number(cfg.staleness_days) || 180) + 'd');\n  // ---- M4 monthly salary stated (hourly only for allowed sectors)\n  const form = (h.wage_form || '').slice(0, 2);\n  const hourly = form === '時給' || sal.type === 'HOURLY';\n  const monthlyMin = hourly ? wageNum(h.wage_monthly_text) : (wageNum(h.wage_monthly_text) || sal.min);\n  const sector = SECTORS.indexOf(e.sector_jp) >= 0 ? e.sector_jp : (SMAP[e.sector_jp] || 'その他');\n  const hourlyOK = hourly && (allowHourly.indexOf(job.sector) >= 0 || allowHourly.indexOf(sector) >= 0);\n  const plausible = monthlyMin && monthlyMin >= 100000 && monthlyMin <= 1000000;\n  G('M4', !!plausible && (!hourly || hourlyOK), !plausible ? 'monthly salary missing/implausible (' + monthlyMin + ')' : 'hourly wage not accepted for this sector');\n  if (hourly) flags.push('hourly_basis_monthly_converted_by_source');\n  // ---- M5 holidays / working conditions\n  const annualHw = Number(String(h.annual_holidays_text || '').replace(/[^0-9]/g, '')) || null;\n  const annual = Number(e.annual_holidays) || annualHw || null;\n  const hasHol = !!annual || (e.holiday_text && e.holiday_text !== 'UNKNOWN');\n  const hasHrs = (e.working_hours && e.working_hours !== 'UNKNOWN') || !!h.workhours1;\n  G('M5', hasHol && hasHrs, !hasHol ? 'holidays missing' : 'working hours missing');\n  if (annual && annual < 105) flags.push('annual_holidays_under_105');\n  // ---- M6 identity & location completeness (MTG definition)\n  const hasLoc = e.prefecture && e.prefecture !== 'UNKNOWN' && ((e.city && e.city !== 'UNKNOWN') || (e.address && e.address !== 'UNKNOWN'));\n  G('M6', !!(hasLoc && cname && (e.job_title_jp && e.job_title_jp !== 'UNKNOWN' || job.title)), 'location/company/title incomplete');\n  // ---- M7 applicable to overseas applicant (explicit domestic-only = fail; silence = pass + flag)\n  const domRx = /国内在住|国内のみ|海外在住.{0,6}不可|現在日本に在住|在留カード.{0,6}(必須|お持ち|所持)/;\n  const dom = e.overseas_applicant === 'DOMESTIC_ONLY' && (norm(e.domestic_evidence_quote).length >= 4 && text.indexOf(norm(e.domestic_evidence_quote)) >= 0) || domRx.test(text);\n  G('M7', !dom, 'domestic-only applicant requirement');\n  if (e.overseas_applicant !== 'OK') flags.push('overseas_applicability_unverified');\n  // ---- M8 source traceable\n  G('M8', /^https:\\/\\//.test(job.detail_url || '') && /^\\d{5}-\\d{8}$/.test(job.job_number || '') && (job.detail_text || '').length > 800, 'source url / job number / text not traceable');\n  const cn = h.corporate_number || (/^[0-9]{13}$/.test(e.corporate_number || '') ? e.corporate_number : '');\n  const norm_e = Object.assign({}, e, { sector_notion: sector, monthly_min: monthlyMin, hourly, annual_holidays_n: annual || null, corporate_number_n: cn, company_name_final: cname });\n  const pass = fails.length === 0;\n  out.push({ json: Object.assign(base, { extract: norm_e, gates, gate_fails: fails, flags, posted_age_days: ageDays, gate_pass: pass, _kind: pass ? 'gated' : 'outcome', status: pass ? 'GATED_PASS' : 'REJECT_GATE', reason: fails.join(' | ') }) });\n}\nreturn out;\n"}, notes: "DETERMINISTIC gates M1-M8. AI output is data only."}, output: [{}]});
